package com.umbra.app.domain.nip77

import com.umbra.app.domain.util.toHex
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * End-to-end reconciliation conformance tests. Every expected message byte sequence and
 * have/need id set below was generated by actually running the reference JS implementation
 * (github.com/hoytech/negentropy, js/Negentropy.js) against the exact same input items, not
 * re-derived from this Kotlin port's own logic — this is what catches a self-consistent but
 * spec-incorrect port, which a test suite written purely from this file's own understanding of
 * the algorithm never could.
 */
class NegentropyReconcilerConformanceTest {

    private fun fakeId(i: Int): String = i.toString(16).padStart(4, '0').repeat(16)

    private fun runReconciliation(
        clientItems: List<Pair<Long, String>>,
        serverItems: List<Pair<Long, String>>
    ): Triple<List<Pair<String, String?>>, List<String>, List<String>> {
        val client = NegentropyReconciler(
            NegentropyStorageVector(clientItems.map { NegentropyItem(it.second, it.first) }),
            isInitiator = true
        )
        val server = NegentropyReconciler(
            NegentropyStorageVector(serverItems.map { NegentropyItem(it.second, it.first) }),
            isInitiator = false
        )

        val messages = mutableListOf<Pair<String, String?>>()
        val haveIds = mutableListOf<String>()
        val needIds = mutableListOf<String>()

        var msg: ByteArray? = client.initiate()
        messages.add("client" to msg!!.toHex())
        var serverTurn = true
        var rounds = 0
        while (msg != null && rounds < 50) {
            rounds++
            if (serverTurn) {
                val result = server.reconcile(msg)
                messages.add("server" to result.outgoingMessage?.toHex())
                msg = result.outgoingMessage
            } else {
                val result = client.reconcile(msg)
                haveIds.addAll(result.haveIds)
                needIds.addAll(result.needIds)
                messages.add("client" to result.outgoingMessage?.toHex())
                msg = result.outgoingMessage
            }
            serverTurn = !serverTurn
        }

        return Triple(messages, haveIds.sorted(), needIds.sorted())
    }

    @Test
    fun `given identical when reconciling then matches reference implementation exactly`() {
        val clientItems: List<Pair<Long, String>> = listOf(
            1000L to fakeId(1),
            1001L to fakeId(2),
            1002L to fakeId(3)
        )
        val serverItems: List<Pair<Long, String>> = listOf(
            1000L to fakeId(1),
            1001L to fakeId(2),
            1002L to fakeId(3)
        )

        val (messages, haveIds, needIds) = runReconciliation(clientItems, serverItems)

        assertEquals(
            listOf(
            "client" to "6100000203000100010001000100010001000100010001000100010001000100010001000100020002000200020002000200020002000200020002000200020002000200020003000300030003000300030003000300030003000300030003000300030003",
            "server" to "6100000203000100010001000100010001000100010001000100010001000100010001000100020002000200020002000200020002000200020002000200020002000200020003000300030003000300030003000300030003000300030003000300030003",
            "client" to null
        ),
            messages
        )
        assertEquals(emptyList<String>(), haveIds)
        assertEquals(emptyList<String>(), needIds)
    }

    @Test
    fun `given client has extra when reconciling then matches reference implementation exactly`() {
        val clientItems: List<Pair<Long, String>> = listOf(
            1000L to fakeId(1),
            1001L to fakeId(2),
            1002L to fakeId(3)
        )
        val serverItems: List<Pair<Long, String>> = listOf(
            1000L to fakeId(1),
            1001L to fakeId(2)
        )

        val (messages, haveIds, needIds) = runReconciliation(clientItems, serverItems)

        assertEquals(
            listOf(
            "client" to "6100000203000100010001000100010001000100010001000100010001000100010001000100020002000200020002000200020002000200020002000200020002000200020003000300030003000300030003000300030003000300030003000300030003",
            "server" to "610000020200010001000100010001000100010001000100010001000100010001000100010002000200020002000200020002000200020002000200020002000200020002",
            "client" to null
        ),
            messages
        )
        assertEquals(listOf(
            "0003000300030003000300030003000300030003000300030003000300030003"
        ), haveIds)
        assertEquals(emptyList<String>(), needIds)
    }

    @Test
    fun `given server has extra when reconciling then matches reference implementation exactly`() {
        val clientItems: List<Pair<Long, String>> = listOf(
            1000L to fakeId(1),
            1001L to fakeId(2)
