        val serverItems: List<Pair<Long, String>> = listOf(
            1000L to fakeId(1),
            1001L to fakeId(2),
            1002L to fakeId(3)
        )

        val (messages, haveIds, needIds) = runReconciliation(clientItems, serverItems)

        assertEquals(
            listOf(
            "client" to "610000020200010001000100010001000100010001000100010001000100010001000100010002000200020002000200020002000200020002000200020002000200020002",
            "server" to "6100000203000100010001000100010001000100010001000100010001000100010001000100020002000200020002000200020002000200020002000200020002000200020003000300030003000300030003000300030003000300030003000300030003",
            "client" to null
        ),
            messages
        )
        assertEquals(emptyList<String>(), haveIds)
        assertEquals(listOf(
            "0003000300030003000300030003000300030003000300030003000300030003"
        ), needIds)
    }

    @Test
    fun `given both empty when reconciling then matches reference implementation exactly`() {
        val clientItems: List<Pair<Long, String>> = emptyList<Pair<Long, String>>()
        val serverItems: List<Pair<Long, String>> = emptyList<Pair<Long, String>>()

        val (messages, haveIds, needIds) = runReconciliation(clientItems, serverItems)

        assertEquals(
            listOf(
            "client" to "6100000200",
            "server" to "6100000200",
            "client" to null
        ),
            messages
        )
        assertEquals(emptyList<String>(), haveIds)
        assertEquals(emptyList<String>(), needIds)
    }

    @Test
    fun `given client empty when reconciling then matches reference implementation exactly`() {
        val clientItems: List<Pair<Long, String>> = emptyList<Pair<Long, String>>()
        val serverItems: List<Pair<Long, String>> = listOf(
            1000L to fakeId(1),
            1001L to fakeId(2)
        )

        val (messages, haveIds, needIds) = runReconciliation(clientItems, serverItems)

        assertEquals(
            listOf(
            "client" to "6100000200",
            "server" to "610000020200010001000100010001000100010001000100010001000100010001000100010002000200020002000200020002000200020002000200020002000200020002",
            "client" to null
        ),
            messages
        )
        assertEquals(emptyList<String>(), haveIds)
        assertEquals(listOf(
            "0001000100010001000100010001000100010001000100010001000100010001",
            "0002000200020002000200020002000200020002000200020002000200020002"
        ), needIds)
    }

